import React, { useState } from 'react';
import { 
  Container, Row, Col, Card, 
  Tab, Tabs, Table, Badge, 
  Button, Alert, Dropdown 
} from 'react-bootstrap';
import { useNavigate } from 'react-router-dom';
import { useFavorites } from '../contexts/FavoritesContext';
import { useNotification } from '../contexts/NotificationContext';

const FavoritesPage = () => {
  const navigate = useNavigate();
  const { favorites, exportFavorites, clearFavorites } = useFavorites();
  const { showNotification } = useNotification();
  
  const [activeTab, setActiveTab] = useState('vendors');

  const handleExport = (type) => {
    try {
      exportFavorites(type);
      showNotification(`Favorites ${type} berhasil diexport`, 'success');
    } catch (error) {
      showNotification('Gagal mengexport favorites', 'error');
    }
  };

  const handleClear = (type) => {
    if (window.confirm(`Yakin ingin menghapus semua favorites ${type}?`)) {
      clearFavorites(type);
      showNotification(`Favorites ${type} berhasil dihapus`, 'success');
    }
  };

  const handleSearch = (item) => {
    if (item.type === 'vendor' || activeTab === 'vendors') {
      navigate(`/vendor?q=${encodeURIComponent(item.name)}`);
    } else if (item.type === 'package' || activeTab === 'packages') {
      navigate(`/package?q=${encodeURIComponent(item.name || item.query)}`);
    }
  };

  return (
    <Container className="py-4">
      <Row className="mb-4">
        <Col>
          <div className="d-flex justify-content-between align-items-center">
            <div>
              <h1 className="display-6 fw-bold">
                <i className="fas fa-star me-2 text-warning"></i>
                Favorites
              </h1>
              <p className="text-muted">
                Kelola data favorit Anda
              </p>
            </div>
            <div>
              <Dropdown>
                <Dropdown.Toggle variant="success" id="dropdown-export">
                  <i className="fas fa-download me-1"></i>
                  Export
                </Dropdown.Toggle>
                <Dropdown.Menu>
                  <Dropdown.Item onClick={() => handleExport('vendors')}>
                    Export Vendors
                  </Dropdown.Item>
                  <Dropdown.Item onClick={() => handleExport('searches')}>
                    Export Searches
                  </Dropdown.Item>
                  <Dropdown.Item onClick={() => handleExport('packages')}>
                    Export Packages
                  </Dropdown.Item>
                  <Dropdown.Divider />
                  <Dropdown.Item onClick={() => handleExport('all')}>
                    Export Semua
                  </Dropdown.Item>
                </Dropdown.Menu>
              </Dropdown>
            </div>
          </div>
        </Col>
      </Row>

      {/* Stats */}
      <Row className="mb-4">
        <Col md={4}>
          <Card className="shadow-sm">
            <Card.Body className="text-center">
              <h3 className="text-warning">{favorites.vendors.length}</h3>
              <p className="text-muted mb-0">Vendor Favorit</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={4}>
          <Card className="shadow-sm">
            <Card.Body className="text-center">
              <h3 className="text-primary">{favorites.searches.length}</h3>
              <p className="text-muted mb-0">Pencarian Favorit</p>
            </Card.Body>
          </Card>
        </Col>
        <Col md={4}>
          <Card className="shadow-sm">
            <Card.Body className="text-center">
              <h3 className="text-success">{favorites.packages.length}</h3>
              <p className="text-muted mb-0">Paket Favorit</p>
            </Card.Body>
          </Card>
        </Col>
      </Row>

      {/* Tabs */}
      <Row>
        <Col>
          <Card className="shadow-sm">
            <Card.Body>
              <Tabs
                activeKey={activeTab}
                onSelect={(k) => setActiveTab(k)}
                className="mb-4"
              >
                <Tab eventKey="vendors" title="Vendors">
                  {favorites.vendors.length > 0 ? (
                    <Table hover responsive>
                      <thead>
                        <tr>
                          <th>Nama Vendor</th>
                          <th>Paket</th>
                          <th>Nilai</th>
                          <th>Tanggal</th>
                          <th>LPSE</th>
                          <th>Aksi</th>
                        </tr>
                      </thead>
                      <tbody>
                        {favorites.vendors.map((vendor) => (
                          <tr key={vendor.favoriteId}>
                            <td>
                              <strong>{vendor.name}</strong>
                            </td>
                            <td>{vendor.package}</td>
                            <td>
                              <Badge bg="warning">{vendor.value}</Badge>
                            </td>
                            <td>{vendor.date}</td>
                            <td>
                              <Badge bg="info">{vendor.lpse}</Badge>
                            </td>
                            <td>
                              <Button
                                size="sm"
                                variant="outline-primary"
                                onClick={() => handleSearch(vendor)}
                              >
                                <i className="fas fa-search"></i>
                              </Button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </Table>
                  ) : (
                    <Alert variant="info" className="text-center">
                      <i className="fas fa-info-circle fa-2x mb-3"></i>
                      <h5>Belum ada vendor favorit</h5>
                      <p>Tambahkan vendor ke favorit dari halaman pencarian</p>
                    </Alert>
                  )}
                  {favorites.vendors.length > 0 && (
                    <div className="text-end">
                      <Button
                        variant="outline-danger"
                        size="sm"
                        onClick={() => handleClear('vendors')}
                      >
                        <i className="fas fa-trash me-1"></i>
                        Hapus Semua Vendors
                      </Button>
                    </div>
                  )}
                </Tab>

                <Tab eventKey="searches" title="Searches">
                  {favorites.searches.length > 0 ? (
                    <Table hover responsive>
                      <thead>
                        <tr>
                          <th>Query</th>
                          <th>Tipe</th>
                          <th>Tanggal Ditambahkan</th>
                          <th>Aksi</th>
                        </tr>
                      </thead>
                      <tbody>
                        {favorites.searches.map((search) => (
                          <tr key={search.favoriteId}>
                            <td>
                              <strong>{search.query || search.name}</strong>
                            </td>
                            <td>
                              <Badge bg={search.type === 'vendor' ? 'primary' : 'success'}>
                                {search.type}
                              </Badge>
                            </td>
                            <td>
                              {new Date(search.addedAt).toLocaleDateString('id-ID')}
                            </td>
                            <td>
                              <Button
                                size="sm"
                                variant="outline-primary"
                                onClick={() => handleSearch(search)}
                              >
                                <i className="fas fa-redo"></i>
                              </Button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </Table>
                  ) : (
                    <Alert variant="info" className="text-center">
                      <i className="fas fa-info-circle fa-2x mb-3"></i>
                      <h5>Belum ada pencarian favorit</h5>
                      <p>Simpan pencarian favorit dari halaman pencarian</p>
                    </Alert>
                  )}
                  {favorites.searches.length > 0 && (
                    <div className="text-end">
                      <Button
                        variant="outline-danger"
                        size="sm"
                        onClick={() => handleClear('searches')}
                      >
                        <i className="fas fa-trash me-1"></i>
                        Hapus Semua Pencarian
                      </Button>
                    </div>
                  )}
                </Tab>

                <Tab eventKey="packages" title="Packages">
                  {favorites.packages.length > 0 ? (
                    <Table hover responsive>
                      <thead>
                        <tr>
                          <th>Nama Paket</th>
                          <th>Nilai</th>
                          <th>Tanggal</th>
                          <th>LPSE</th>
                          <th>Aksi</th>
                        </tr>
                      </thead>
                      <tbody>
                        {favorites.packages.map((pkg) => (
                          <tr key={pkg.favoriteId}>
                            <td>
                              <strong>{pkg.name || pkg.package}</strong>
                            </td>
                            <td>
                              <Badge bg="warning">{pkg.value}</Badge>
                            </td>
                            <td>{pkg.date}</td>
                            <td>
                              <Badge bg="info">{pkg.lpse}</Badge>
                            </td>
                            <td>
                              <Button
                                size="sm"
                                variant="outline-primary"
                                onClick={() => handleSearch(pkg)}
                              >
                                <i className="fas fa-external-link-alt"></i>
                              </Button>
                            </td>
                          </tr>
                        ))}
                      </tbody>
                    </Table>
                  ) : (
                    <Alert variant="info" className="text-center">
                      <i className="fas fa-info-circle fa-2x mb-3"></i>
                      <h5>Belum ada paket favorit</h5>
                      <p>Tambahkan paket ke favorit dari halaman pencarian paket</p>
                    </Alert>
                  )}
                  {favorites.packages.length > 0 && (
                    <div className="text-end">
                      <Button
                        variant="outline-danger"
                        size="sm"
                        onClick={() => handleClear('packages')}
                      >
                        <i className="fas fa-trash me-1"></i>
                        Hapus Semua Paket
                      </Button>
                    </div>
                  )}
                </Tab>
              </Tabs>
            </Card.Body>
          </Card>
        </Col>
      </Row>
    </Container>
  );
};

export default FavoritesPage;